export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const T = u / g, H = u * u / (2 * g);
  const t = Math.max(0, time);
  const ty = u * t - g * t * t / 2;
  const tv = u - g * t;
  const tau = t - T;
  const released = tau >= 0;
  const dy = released ? H - g * tau * tau / 2 : H;
  const dv = released ? -g * tau : 0;
  const da = released ? -g : 0;
  const ta = -g;
  const top = 380, sc = 270 / 2.2;
  const Y = h => top - h * sc;
  const xt = 160, xd = 480;
  const st = t < 0.0001 ? 'At launch' : (Math.abs(tau) < 0.0001 ? 'At the top' : (t < T ? 'Rising' : (ty <= 0.0001 ? 'At launch height' : 'Falling')));
  const sd = !released ? (t < 0.0001 ? 'Held in place' : 'Held in place') : (ty <= 0.0001 ? 'At launch height' : (tau < 0.15 ? 'Just released' : 'Falling together'));
  const o = [];
  o.push(...sdk.panel({ id: 'lane.toss', x: 10, y: 40, w: 305, h: 360, title: 'Toss', state: st }));
  o.push(...sdk.panel({ id: 'lane.drop', x: 325, y: 40, w: 305, h: 360, title: 'Drop', state: sd }));
  o.push(...sdk.groundMark('mark.toss', xt, Y(0) + 14, 80, 'Launch'));
  o.push(...sdk.gate('gate', xd, Y(H) + 14, { open: released, label: '' }));
  if (released) o.push(sdk.circle('ghost.drop', xd, Y(H), 24, { opacity: 0.25 }));
  o.push(sdk.circle('ball.toss', xt, Y(ty), 26));
  o.push(sdk.circle('ball.drop', xd, Y(dy), 26));
  o.push(...sdk.vector('vec.v.toss', { x: xt - 30, y: Y(ty) }, { value: tv, direction: 'up' }, { scale: 8, label: 'v' }));
  o.push(...sdk.vector('vec.a.toss', { x: xt + 30, y: Y(ty) }, { value: ta, direction: 'up' }, { scale: 4, label: 'a' }));
  o.push(...sdk.vector('vec.v.drop', { x: xd - 30, y: Y(dy) }, { value: dv, direction: 'up' }, { scale: 8, label: 'v' }));
  o.push(...sdk.vector('vec.a.drop', { x: xd + 30, y: Y(dy) }, { value: da, direction: 'up' }, { scale: 4, label: 'a' }));
  o.push(...sdk.callout(xt + 50, Y(ty) - 30, ['v ' + sdk.format(tv, 2) + ' m/s', 'a ' + sdk.format(ta, 1) + ' m/s²'], { id: 'callout.toss' }));
  o.push(...sdk.callout(xd + 50, Y(dy) - 30, ['v ' + sdk.format(dv, 2) + ' m/s', 'a ' + sdk.format(da, 1) + ' m/s²'], { id: 'callout.drop' }));
  const ro = [{ id: 'tossedVelocity', value: tv }, { id: 'tossedAcceleration', value: ta }, { id: 'dropVelocity', value: dv }, { id: 'dropAcceleration', value: da }];
  return { frame: { width: 640, height: 420, objects: o, readouts: ro }, quantities: { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: tv, tossedAcceleration: ta, tossedHeight: ty, dropVelocity: dv, dropAcceleration: da, dropHeight: dy } };
}
